pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address recipient, uint256 etherAmount) public {
        // Bound etherAmount to a reasonable range to avoid overflow issues
        etherAmount = bound(etherAmount, 1, 1000 ether);
        // Assume recipient is not the zero address and not the owner (address(this))
        vm.assume(recipient != address(0) && recipient != address(this));

        // Deploy a helper that reverts on receiving Ether
        Reverter reverter = new Reverter();

        // Fund the contract with etherAmount
        vm.deal(address(c), etherAmount);
        uint256 contractBalanceBefore = address(c).balance;
        uint256 reverterBalanceBefore = address(reverter).balance;

        bool success;
        // The owner (address(this)) calls withdrawAll with the Reverter as recipient
        try c.withdrawAll(address(reverter)) {
            success = true;
        } catch {
            success = false;
        }

        // Universal property: if the recipient is a contract that reverts on receive, 
        // the call MUST revert. The reference contract's transfer fails because 
        // recipient reverts, success is false. The mutant sends to msg.sender (the owner) 
        // which does not revert, so success is true. We assert that success is false.
        assertTrue(!success);
    }
}

