pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 initialBalance, address recipient) public {
        // Keep initialBalance within reasonable bounds to avoid overflow and ensure sufficient funds
        vm.assume(initialBalance > 0);
        vm.assume(initialBalance <= address(c).balance + initialBalance); // Prevent overflow

        // Fund the contract with fuzzed initial balance
        vm.deal(address(c), initialBalance);

        // Exclude zero address and precompile/self to avoid trivial failures
        vm.assume(recipient != address(0));
        vm.assume(recipient != address(this));
        vm.assume(recipient != address(c));

        uint256 balanceBefore = recipient.balance;
        uint256 contractBalanceBefore = address(c).balance;

        // Owner (address(this)) triggers withdrawAll
        c.withdrawAll(recipient);

        uint256 balanceAfter = recipient.balance;
        uint256 contractBalanceAfter = address(c).balance;

        // General rule: recipient balance must increase exactly by the contract's entire pre-call balance,
        // leaving the contract with zero balance. This holds for the reference C, but fails for the buggy version
        // when no transfer occurs.
        assertTrue(
            balanceAfter == balanceBefore + contractBalanceBefore &&
            contractBalanceAfter == 0
        );
    }
}

contract InvMutTest {
    C public c;

    constructor(C _c) {
        c = _c;
    }

    function test(address ownerCandidate, address recipient, uint256 amount) public {
        require(address(this).balance >= amount);
        bool success = true;

        // Attempt withdrawal as the given owner candidate
        try c.withdrawAll{value: amount}(recipient) {
            success = true;
        } catch {
            success = false;
        }

        // Rule: withdrawal succeeds only if the caller is the actual owner
        assert(success == (ownerCandidate == c.owner()));
    }
}

